type CollectorConfigurationComponents struct {
	// Trace Java services with eBPF.
	EbpfJavaAgent *bool `pulumi:"ebpfJavaAgent"`
	// Collect host metrics with eBPF.
	EbpfMetrics *bool `pulumi:"ebpfMetrics"`
	// Service map and request rate, error and duration metrics with eBPF.
	EbpfRedMetrics *bool `pulumi:"ebpfRedMetrics"`
	// Basic distributed tracing with eBPF.
	EbpfTracingBasic *bool `pulumi:"ebpfTracingBasic"`
	// Full distributed tracing with eBPF.
	EbpfTracingFull *bool `pulumi:"ebpfTracingFull"`
	// Collect the collector's own logs.
	LogsCollectorInternals *bool `pulumi:"logsCollectorInternals"`
	// Collect logs of Docker containers that use the default json-file logging driver.
	LogsDocker *bool `pulumi:"logsDocker"`
	// Collect logs from the host's /var/log directory.
	LogsHost *bool `pulumi:"logsHost"`
	// Collect Kubernetes container logs and events.
	LogsKubernetes *bool `pulumi:"logsKubernetes"`
	// Collect Apache metrics.
	MetricsApache *bool `pulumi:"metricsApache"`
	// Collect Kubernetes object state metrics, such as pods, workloads, nodes and volumes.
	MetricsCluster *bool `pulumi:"metricsCluster"`
	// Former name of `metricsCluster`. It reads back as `metricsCluster` does. Write `metricsCluster` instead.
	MetricsDatabases *bool `pulumi:"metricsDatabases"`
	// Collect Elasticsearch metrics.
	MetricsElasticsearch *bool `pulumi:"metricsElasticsearch"`
	// Collect CPU, memory, disk, filesystem and network metrics of the host.
	MetricsHostOs *bool `pulumi:"metricsHostOs"`
	// Collect MySQL metrics.
	MetricsMysql *bool `pulumi:"metricsMysql"`
	// Collect Nginx metrics.
	MetricsNginx *bool `pulumi:"metricsNginx"`
	// Collect Redis, MongoDB, Memcached and Kafka metrics.
	MetricsOtherDatabases *bool `pulumi:"metricsOtherDatabases"`
	// Collect PgBouncer metrics.
	MetricsPgbouncer *bool `pulumi:"metricsPgbouncer"`
	// Collect PostgreSQL metrics.
	MetricsPostgres *bool `pulumi:"metricsPostgres"`
	// Collect the host's process and thread counts. It can use significant CPU on a host that runs very many processes.
	MetricsProcessStatistics *bool `pulumi:"metricsProcessStatistics"`
	// Collect Traefik metrics.
	MetricsTraefik *bool `pulumi:"metricsTraefik"`
	// Accept OpenTelemetry traces from your SDKs over OTLP.
	TracesOpentelemetry *bool `pulumi:"tracesOpentelemetry"`
}

